 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('contact-form');
     const nameInput = document.getElementById('full-name');
     const emailInput = document.getElementById('email');
     const phoneInput = document.getElementById('phone');
     const statusMessage = document.getElementById('form-status');

     const validators = {
         name: (val) => {
             if (!val.trim()) return 'Full name is required.';
             return '';
         },
         email: (val) => {
             if (!val.trim()) return 'Email address is required.';
             const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
             if (!emailRegex.test(val)) return 'Please enter a valid email address.';
             return '';
         },
         phone: (val) => {
             if (!val.trim()) return ''; // Optional
             const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
             if (!phoneRegex.test(val)) return 'Format must be 123-456-7890.';
             return '';
         }
     };

     const validateField = (input, validator, errorId) => {
         const errorElement = document.getElementById(errorId);
         const errorMessage = validator(input.value);

         if (errorMessage) {
             input.classList.add('invalid');
             errorElement.textContent = errorMessage;
             input.setAttribute('aria-invalid', 'true');
             return false;
         } else {
             input.classList.remove('invalid');
             errorElement.textContent = '';
             input.removeAttribute('aria-invalid');
             return true;
         }
     };

     const handleBlur = (e) => {
         const id = e.target.id;
         if (id === 'full-name') validateField(nameInput, validators.name, 'name-error');
         if (id === 'email') validateField(emailInput, validators.email, 'email-error');
         if (id === 'phone') validateField(phoneInput, validators.phone, 'phone-error');
     };

     nameInput.addEventListener('blur', handleBlur);
     emailInput.addEventListener('blur', handleBlur);
     phoneInput.addEventListener('blur', handleBlur);

     form.addEventListener('submit', (e) => {
         e.preventDefault();

         const isNameValid = validateField(nameInput, validators.name, 'name-error');
         const isEmailValid = validateField(emailInput, validators.email, 'email-error');
         const isPhoneValid = validateField(phoneInput, validators.phone, 'phone-error');

         if (isNameValid && isEmailValid && isPhoneValid) {
             statusMessage.textContent = 'Thank you! Your message has been sent.';
             statusMessage.className = 'success-text';
             form.reset();
             // Remove validation classes after reset
             [nameInput, emailInput, phoneInput].forEach(input => input.classList.remove('invalid'));
         } else {
             statusMessage.textContent = 'Please correct the errors above.';
             statusMessage.className = 'error-message';
         }
     });
 });

